func fetchAll(urls []string) []string {
  var results []string
  var wg sync.WaitGroup
  for _, u := range urls {
    wg.Add(1)
    go func(url string) {
      defer wg.Done()
      resp, _ := http.Get(url)
      if resp != nil {
        body, _ := io.ReadAll(resp.Body)
        results = append(results, string(body))
      }
    }(u)
  }
  wg.Wait()
  return results
